// Make the project look as if an older UDS had written a standard that this UDS no longer ships, then run uds on it.
// usage: node prune-case.cjs <uds.js> <uds arguments...>
const fs = require('fs'), path = require('path'), cp = require('child_process'), crypto = require('crypto');
const [bin, ...udsArgs] = process.argv.slice(2);
const rel = '.standards/retired-by-uds.ai.yaml';
const body = '# a standard an older UDS wrote and this UDS no longer ships\n';
fs.writeFileSync(rel, body);
const manifestPath = path.join('.standards', 'manifest.json');
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
manifest.upstream.version = '6.9.0';
manifest.fileHashes = manifest.fileHashes || {};
manifest.fileHashes[rel] = { hash: 'sha256:' + crypto.createHash('sha256').update(body).digest('hex'), size: body.length, installedAt: new Date().toISOString() };
fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + '\n');
const r = cp.spawnSync(process.execPath, [bin, ...udsArgs], { encoding: 'utf8', env: process.env });
process.stdout.write((r.stdout || '') + (r.stderr || '') + '\nRETIRED-STANDARD-FILE-EXISTS=' + fs.existsSync(rel) + '\n');
process.exit(r.status === null ? 1 : r.status);

const https = require('https');
const { EventEmitter } = require('events');
const doc = JSON.stringify({ 'dist-tags': { latest: '6.0.0', beta: '99.0.0-beta.1' } });
https.get = function (url, opts, cb) {
  if (typeof opts === 'function') cb = opts;
  const req = new EventEmitter();
  req.destroy = () => {};
  process.nextTick(() => {
    const res = new EventEmitter();
    res.statusCode = 200;
    cb(res);
    res.emit('data', doc);
    res.emit('end');
  });
  return req;
};
